import { test, expect } from '@playwright/test';

test.describe('Countdown Timer', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/countdown');
  });

  test('should update countdown timer every second', async ({ page }) => {
    // Verify initial countdown value
    const countdownDisplay = page.getByTestId('countdown-display');
    await expect(countdownDisplay).toContainText('10');

    // Verify timer interval is set
    const timerInterval = page.getByTestId('timer-interval');
    await expect(timerInterval).toBeVisible();

    // Wait for 1 second
    await page.waitForTimeout(1000);

    // Verify countdown decremented
    await expect(countdownDisplay).toContainText('9');

    // Wait for another second
    await page.waitForTimeout(1000);

    // Verify countdown decremented again
    await expect(countdownDisplay).toContainText('8');

    // Wait for 10 seconds to reach zero
    await page.waitForTimeout(10000);

    // Verify countdown reaches zero
    await expect(countdownDisplay).toContainText('0');

    // Verify timer is stopped
    const timerButton = page.getByRole('button', { name: /stop/i });
    await expect(timerButton).toBeVisible();
  });

  test('should handle countdown reaching zero and display finished message', async ({ page }) => {
    // Set initial countdown to 5
    const countdownInput = page.getByLabel('Countdown Value');
    await countdownInput.fill('5');

    // Click start button
    const startButton = page.getByRole('button', { name: /start/i });
    await startButton.click();

    // Verify countdown starts at 5
    const countdownDisplay = page.getByTestId('countdown-display');
    await expect(countdownDisplay).toContainText('5');

    // Wait for 5 seconds
    await page.waitForTimeout(5100);

    // Verify countdown reaches zero
    await expect(countdownDisplay).toContainText('0');

    // Verify finished message is displayed
    const finishedMessage = page.getByTestId('finished-message');
    await expect(finishedMessage).toBeVisible();
    await expect(finishedMessage).toContainText('Time is up');

    // Verify timer is disabled
    await expect(startButton).toBeDisabled();
  });
});
